  /** helper function to check EvidenceCoherence_cargo_coordination_process_evidence_coherence's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param recovery_transition method that will be called with the value of the outgoing data
   *        port 'recovery_transition'.
   * @param coordination_guard method that will be called with the value of the outgoing data
   *        port 'coordination_guard'.
   * @param coordination_frame method that will be called with the value of the outgoing data
   *        port 'coordination_frame'.
   * @param ship_update method that will be called with the value of the outgoing data
   *        port 'ship_update'.
   * @param warehouse_update method that will be called with the value of the outgoing data
   *        port 'warehouse_update'.
   * @param priority_directive method that will be called with the value of the outgoing data
   *        port 'priority_directive'.
   */
  def check_concrete_output(recovery_transition: Mining_Cargo_Transfer_Evidence_Coordinator.RecoveryTransition => B,
                            coordination_guard: Mining_Cargo_Transfer_Evidence_Coordinator.CoordinationGuard => B,
                            coordination_frame: Mining_Cargo_Transfer_Evidence_Coordinator.CoordinationFrame => B,
                            ship_update: Mining_Cargo_Transfer_Evidence_Coordinator.ShipUpdate.Type => B,
                            warehouse_update: Mining_Cargo_Transfer_Evidence_Coordinator.WarehouseUpdate.Type => B,
                            priority_directive: Mining_Cargo_Transfer_Evidence_Coordinator.PriorityDirective => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val recovery_transitionValue: Mining_Cargo_Transfer_Evidence_Coordinator.RecoveryTransition = get_recovery_transition().get
    if(!recovery_transition(recovery_transitionValue)) {
      testFailures = testFailures :+ st"'recovery_transition' did not match expected: value of the outgoing data port is ${recovery_transitionValue}"
    }
    val coordination_guardValue: Mining_Cargo_Transfer_Evidence_Coordinator.CoordinationGuard = get_coordination_guard().get
    if(!coordination_guard(coordination_guardValue)) {
      testFailures = testFailures :+ st"'coordination_guard' did not match expected: value of the outgoing data port is ${coordination_guardValue}"
    }
    val coordination_frameValue: Mining_Cargo_Transfer_Evidence_Coordinator.CoordinationFrame = get_coordination_frame().get
    if(!coordination_frame(coordination_frameValue)) {
      testFailures = testFailures :+ st"'coordination_frame' did not match expected: value of the outgoing data port is ${coordination_frameValue}"
    }
    val ship_updateValue: Mining_Cargo_Transfer_Evidence_Coordinator.ShipUpdate.Type = get_ship_update().get
    if(!ship_update(ship_updateValue)) {
      testFailures = testFailures :+ st"'ship_update' did not match expected: value of the outgoing data port is ${ship_updateValue}"
    }
    val warehouse_updateValue: Mining_Cargo_Transfer_Evidence_Coordinator.WarehouseUpdate.Type = get_warehouse_update().get
    if(!warehouse_update(warehouse_updateValue)) {
      testFailures = testFailures :+ st"'warehouse_update' did not match expected: value of the outgoing data port is ${warehouse_updateValue}"
    }
    val priority_directiveValue: Mining_Cargo_Transfer_Evidence_Coordinator.PriorityDirective = get_priority_directive().get
    if(!priority_directive(priority_directiveValue)) {
      testFailures = testFailures :+ st"'priority_directive' did not match expected: value of the outgoing data port is ${priority_directiveValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


